BUILD_DEPARTMENTS_PY = '#!/usr/bin/env python3\n"""Build Pharmaceutical Encyclopedia department & route-of-administration datasets (Pill by Pill v6.0b).\n\nGenerates `site/data/departments.json` covering:\n  - Formulation Development & Routes of Administration (`formulation`)\n  - Analytical Development & Quality Control (`analytical`)\n  - Early-Stage Discovery & Preclinical (`discovery`)\n  - Commercial Manufacturing & Bioprocessing (`manufacturing`)\n\nOptionally scans `site/data/drugs/*.json` (when present) to compute live catalogue counts\nby modality/route so every department links directly into the 3,379-medicine catalogue.\n\nUsage:\n  python3 pipeline/build_departments.py site/data\n"""\nimport json\nimport pathlib\nimport sys\n\nCHECKED = "2026-11-20"\n\nROUTES_OF_ADMINISTRATION = [\n    {\n        "id": "oral-solid",\n        "name": "Oral Solid Dosage (Tablets & Capsules)",\n        "plain_summary": "Swallowed pills and capsules are the most common way to take medicine because they are easy to store, transport, and take at home without needles.",\n        "technical_rationale": "Preferred for chemically stable small molecules with adequate aqueous solubility and intestinal permeability (BCS Classes I–IV). Subject to gastric pH degradation and hepatic first-pass metabolism; modified-release coatings or matrices control plasma Cmax and dosing frequency.",\n        "cqas": ["Assay & content uniformity", "Dissolution profile (USP <711>)", "Disintegration & tablet friability", "Related substances / degradation products", "Water activity & residual solvents"],\n        "equipment_ids": ["eq-rotary-tablet-press", "eq-fluid-bed-granulator", "eq-dissolution-bath", "eq-hplc-uplc"],\n        "catalogue_filter": "#/ref/drugs?type=sm",\n        "sources": [\n            {"label": "FDA Guidance: Q8(R2) Pharmaceutical Development", "url": "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q8r2-pharmaceutical-development"},\n            {"label": "FDA Guidance: Dissolution Testing of Immediate Release Solid Oral Dosage Forms", "url": "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/dissolution-testing-immediate-release-solid-oral-dosage-forms"},\n        ],\n    },\n    {\n        "id": "sterile-parenteral",\n        "name": "Sterile Parenteral (IV, SC & IM Injectables)",\n        "plain_summary": "Injections and IV drips send medicine directly into the bloodstream or under the skin—essential for proteins, antibodies, and emergencies where pills would be digested in the stomach.",\n        "technical_rationale": "Bypasses gastrointestinal proteolysis and first-pass hepatic clearance, delivering 100% bioavailability (IV) or controlled depot absorption (SC/IM). Requires strict sterility assurance, endotoxin control, sub-visible particulate limits, and often lyophilization for unstable biologics.",\n        "cqas": ["Sterility & container-closure integrity (CCI)", "Bacterial endotoxins (USP <85>)", "Sub-visible & visible particulates (USP <788>)", "pH, osmolality & viscosity (SC syringability)", "Protein aggregation / sub-visible dimers"],\n        "equipment_ids": ["eq-lyophilizer", "eq-sterile-fill-finish", "eq-single-use-bioreactor", "eq-hplc-uplc"],\n        "catalogue_filter": "#/ref/drugs?type=ab",\n        "sources": [\n            {"label": "FDA Guidance: Sterile Drug Products Produced by Aseptic Processing — cGMP", "url": "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/sterile-drug-products-produced-aseptic-processing-current-good-manufacturing-practice"},\n        ],\n    },\n    {\n        "id": "lnp-oligo",\n        "name": "Lipid Nanoparticles (LNP) & Oligonucleotide Delivery",\n        "plain_summary": "Gene-targeted RNA medicines are fragile and cannot enter cells alone, so scientists wrap them in microscopic fat droplets (lipid nanoparticles) or attach sugar homing tags (GalNAc).",\n        "technical_rationale": "Ionizable cationic lipids encapsulate polyanionic siRNA or mRNA via microfluidic rapid mixing, protecting cargo from serum nucleases and enabling endosomal escape. Alternatively, trivalent GalNAc conjugation targets hepatic ASGPR receptors for subcutaneous delivery.",\n        "cqas": ["Particle size distribution (PDI) & zeta potential", "Encapsulation efficiency (%)", "Lipid identity & ionizable lipid ratio", "Oligonucleotide strand purity & sequence identity", "Sterility & endotoxin"],\n        "equipment_ids": ["eq-sterile-fill-finish", "eq-lc-ms-ms", "eq-hplc-uplc"],\n        "catalogue_filter": "#/ref/drugs?type=ol",\n        "sources": [\n            {"label": "FDA Guidance: Drug Products, Including Biological Products, that Contain Nanomaterials", "url": "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/drug-products-including-biological-products-contain-nanomaterials-guidance-industry"},\n        ],\n    },\n    {\n        "id": "inhaled-pulmonary",\n        "name": "Inhaled & Pulmonary (MDI, DPI & Nebulizers)",\n        "plain_summary": "Inhalers and nebulizers deliver medicine straight into the lungs as a fine mist or dry powder so it acts quickly on airways with lower doses than a pill.",\n        "technical_rationale": "Targets local respiratory receptors (beta-2 agonists, inhaled corticosteroids) or rapid alveolar absorption while minimizing systemic exposure. Performance depends on aerodynamic particle size distribution (typically 1–5 µm respirable fraction) and device-formulation pairing.",\n        "cqas": ["Aerodynamic particle size distribution (APSD)", "Delivered dose uniformity (DDU)", "Spray pattern & plume geometry (MDIs)", "Extractables & leachables from device components", "Moisture sensitivity (DPIs)"],\n        "equipment_ids": ["eq-hplc-uplc", "eq-karl-fischer", "eq-stability-chamber"],\n        "catalogue_filter": "#/ref/drugs?atc=R",\n        "sources": [\n            {"label": "FDA Guidance: Metered Dose Inhaler (MDI) and Dry Powder Inhaler (DPI) Quality Considerations", "url": "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/metered-dose-inhaler-mdi-and-dry-powder-inhaler-dpi-drug-products-quality-considerations"},\n        ],\n    },\n    {\n        "id": "ophthalmic-transdermal",\n        "name": "Ophthalmic, Topical & Transdermal Systems",\n        "plain_summary": "Eye drops, creams, and skin patches deliver medicine right where it is needed—or steadily through the skin over hours or days.",\n        "technical_rationale": "Ophthalmic solutions/suspensions require sterility, isotonicity, and preservative compatibility; transdermal delivery systems (TDS) provide zero-order systemic release across the stratum corneum while avoiding GI and hepatic first-pass variability.",\n        "cqas": ["Sterility & antimicrobial effectiveness (ophthalmic)", "In vitro permeation / release testing (IVPT / IVRT)", "Adhesion & cold-flow stability (patches)", "Viscosity & drop-size uniformity"],\n        "equipment_ids": ["eq-sterile-fill-finish", "eq-hplc-uplc", "eq-stability-chamber"],\n        "catalogue_filter": "#/ref/drugs?atc=S",\n        "sources": [\n            {"label": "FDA Guidance: Transdermal and Topical Delivery Systems — Product Development and Quality Considerations", "url": "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/transdermal-and-topical-delivery-systems-product-development-and-quality-considerations"},\n        ],\n    },\n]\n\nDEPARTMENTS = [\n    {\n        "id": "formulation",\n        "name": "Formulation Development & Routes of Administration",\n        "icon": "💊",\n        "stage_range": "Preclinical → Phase III",\n        "status": "complete",\n        "plain_summary": "An active drug molecule by itself is rarely usable—it might taste awful, dissolve poorly, or break down in stomach acid. Formulation scientists design the exact tablet, capsule, sterile liquid, inhaler, or nanoparticle that gets the medicine safely to its target in the body.",\n        "technical_summary": "Bridges drug substance (API) physicochemical profiling (preformulation: pKa, logP, polymorph screening, excipient compatibility) to robust drug product design under Quality by Design (ICH Q8(R2)). Selects the route of administration, excipient matrix, and scalable unit operations (granulation, compression, lyophilization, aseptic fill-finish).",\n        "workflows": [\n            {"step": "1. Preformulation & Solid-State Characterization", "plain": "Test how the raw drug powder dissolves, absorbs water, and holds up to heat and light.", "expert": "Polymorph & salt screening, BCS solubility/permeability profiling, hygroscopicity (DVS), and binary excipient compatibility."},\n            {"step": "2. Dosage Form & Excipient Design", "plain": "Choose inactive ingredients (binders, coatings, buffers, or lipids) that protect the medicine and control how fast it releases.", "expert": "Excipient selection via FDA Inactive Ingredient Database (IID), release-rate architecture (IR, enteric DR, HPMC/OROS ER, depot, LNP), and tonicity/pH buffering for injectables."},\n            {"step": "3. Process Development & Scale-Up", "plain": "Turn a small lab recipe into a repeatable factory process that makes thousands of identical doses per hour.", "expert": "Unit operation optimization (high-shear/fluid-bed granulation, roller compaction, rotary compression, lyophilization cycle design, microfluidic LNP mixing) with Design Space characterization."},\n            {"step": "4. Packaging & Container-Closure Integrity", "plain": "Pick bottles, blisters, vials, or prefilled syringes that keep moisture, oxygen, and germs out.", "expert": "Extractables & leachables (E&L) evaluation, moisture vapor transmission rate (MVTR), and Container-Closure Integrity Testing (CCIT) for sterile products."},\n        ],\n        "regulatory_anchors": [\n            {"label": "ICH Q8(R2) Pharmaceutical Development (FDA)", "url": "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q8r2-pharmaceutical-development"},\n            {"label": "FDA Inactive Ingredient Database (IID)", "url": "https://www.accessdata.fda.gov/scripts/cder/iig/index.cfm"},\n        ],\n        "equipment_ids": ["eq-rotary-tablet-press", "eq-fluid-bed-granulator", "eq-lyophilizer", "eq-sterile-fill-finish"],\n        "related_links": [\n            {"title": "Routes of Administration Guide", "href": "#/ref/routes", "text": "Compare oral solid, sterile parenteral, LNP/oligo, inhaled, and topical delivery."},\n            {"title": "Excipients & PK Release Simulator", "href": "#/ref/topic/excipients", "text": "See how IR, enteric, extended-release, and depot designs shape blood levels."},\n        ],\n    },\n    {\n        "id": "analytical",\n        "name": "Analytical Development & Quality Control (QC)",\n        "icon": "🔬",\n        "stage_range": "Preclinical → Commercial Release",\n        "status": "complete",\n        "plain_summary": "Analytical scientists are the detectives and referees of medicine-making. They build ultra-sensitive tests to prove every batch has the exact right amount of medicine, no harmful impurities, and stays potent until the expiration date on the box.",\n        "technical_summary": "Develops, qualifies, and validates phase-appropriate analytical methods (ICH Q2(R2)) to measure identity, assay/potency, impurities (ICH Q3A/B/C/D), dissolution (USP <711>), and shelf-life stability (ICH Q1A(R2)). Transfers validated methods to cGMP QC release laboratories operating under 21 CFR Part 211 and 21 CFR Part 11 data integrity controls.",\n        "workflows": [\n            {"step": "1. Method Development & Forced Degradation", "plain": "Intentionally stress the drug with heat, light, acid, or oxygen to make sure the test can spot any breakdown products.", "expert": "Stability-indicating chromatographic method development (RP-HPLC/UPLC, HILIC, SEC, IEX) verified by forced degradation and mass-balance studies."},\n            {"step": "2. Method Validation (ICH Q2(R2))", "plain": "Prove the test gives accurate, repeatable answers every time, in any lab.", "expert": "Validation of specificity, linearity/range, accuracy, precision (repeatability & intermediate), LOD/LOQ, and robustness prior to Phase III/NDA filing."},\n            {"step": "3. Impurity & Elemental Profiling (ICH Q3)", "plain": "Hunt for trace leftover chemicals, nitrosamines, or heavy metals down to parts per billion.", "expert": "Trace organic impurities & nitrosamine risk assessment via LC-MS/MS and GC-MS; elemental impurities (Cd, Pb, As, Hg) via ICP-MS per ICH Q3D; residual solvents per ICH Q3C."},\n            {"step": "4. Stability & Batch Release Testing (QC)", "plain": "Store batches in climate chambers for months or years and test every finished lot before patients receive it.", "expert": "Real-time (25 °C/60% RH or 2–8 °C) and accelerated (40 °C/75% RH) ICH Q1A stability protocols, Certificate of Analysis (CoA) release, and OOS/OOT investigations."},\n        ],\n        "regulatory_anchors": [\n            {"label": "ICH Q2(R2) Validation of Analytical Procedures (FDA)", "url": "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q2r2-validation-analytical-procedures"},\n            {"label": "ICH Q1A(R2) Stability Testing of New Drug Substances and Products (FDA)", "url": "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q1ar2-stability-testing-new-drug-substances-and-products"},\n            {"label": "ICH Q3D Elemental Impurities (FDA)", "url": "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q3dr2-guideline-elemental-impurities"},\n            {"label": "FDA 21 CFR Part 11 Electronic Records & Signatures Guidance", "url": "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/part-11-electronic-records-electronic-signatures-scope-and-application"},\n        ],\n        "equipment_ids": ["eq-hplc-uplc", "eq-lc-ms-ms", "eq-dissolution-bath", "eq-karl-fischer", "eq-stability-chamber", "eq-icp-ms"],\n        "related_links": [\n            {"title": "Equipment Market & Specs", "href": "#/ref/equipment", "text": "Inspect analytical hardware, leading OEMs, and public/secondary pricing bands."},\n            {"title": "Manufacturers & Site Audits", "href": "#/ref/vendors", "text": "Compare facility FDA Form 483 lab-control and data-integrity records."},\n        ],\n    },\n    {\n        "id": "discovery",\n        "name": "Early-Stage Discovery & Preclinical R&D",\n        "icon": "🧬",\n        "stage_range": "Target ID → IND Filing",\n        "status": "scaffold",\n        "plain_summary": "Before a medicine is ever tested in people, scientists identify the biological target behind a disease, test thousands of candidate molecules, image how the best ones lock into their target in 3D, and check basic safety.",\n        "technical_summary": "Encompasses target validation, high-throughput screening (HTS), hit-to-lead medicinal chemistry or antibody discovery (phage display/hybridoma), structural biology (X-ray crystallography, cryo-EM, NMR), in vitro ADME/PK, and Good Laboratory Practice (GLP, 21 CFR Part 58) nonclinical safety studies supporting an IND submission.",\n        "workflows": [\n            {"step": "1. Target Identification & High-Throughput Screening", "plain": "Screen thousands of molecules with lab robots to find initial \'hits\' that affect a disease protein.", "expert": "Biochemical and cell-based HTS assays using automated liquid handlers and multimode plate readers."},\n            {"step": "2. Structural Biology & Lead Optimization", "plain": "Map the 3D atomic pocket of the target so chemists can reshape the molecule for a tighter, safer fit.", "expert": "Structure-based drug design (SBDD) via X-ray crystallography, cryo-EM, and NMR—directly reflected in this site\'s 485 PDB binding-site animations."},\n            {"step": "3. Preclinical ADME/PK & GLP Toxicology", "plain": "Verify how the candidate moves through the body and establish safe starting doses before Phase I human trials.", "expert": "Metabolic stability, CYP inhibition, hERG cardiac safety, and multi-species GLP toxicology studies under 21 CFR Part 58."},\n        ],\n        "regulatory_anchors": [\n            {"label": "FDA Step 1 & 2: Discovery, Development & Preclinical Research", "url": "https://www.fda.gov/patients/drug-development-process/step-1-discovery-and-development"},\n            {"label": "FDA Good Laboratory Practice (GLP) Regulations (21 CFR Part 58)", "url": "https://www.ecfr.gov/current/title-21/chapter-I/subchapter-A/part-58"},\n        ],\n        "equipment_ids": ["eq-hts-liquid-handler", "eq-lc-ms-ms"],\n        "related_links": [\n            {"title": "3D Experimental Binding Animations (485)", "href": "#/ref/drugs?has=binding", "text": "Explore real PDB crystal and cryo-EM drug-target pockets."},\n            {"title": "Medicine Families (297 Trees)", "href": "#/ref/families", "text": "See how follow-on drugs evolved from first-in-class discoveries."},\n        ],\n    },\n    {\n        "id": "manufacturing",\n        "name": "Commercial Manufacturing & Bioprocessing",\n        "icon": "🏭",\n        "stage_range": "Phase III / PPQ → Commercial",\n        "status": "scaffold",\n        "plain_summary": "Making a few grams in a research lab is very different from making millions of sterile, identical doses for hospitals and pharmacies around the world. Commercial manufacturing scales up chemistry or living cell factories under strict cleanroom rules.",\n        "technical_summary": "Covers API chemical synthesis scale-up or upstream/downstream biologics processing (cell culture bioreactors, harvest, Protein A / ion-exchange chromatography, tangential flow filtration, viral clearance), Process Performance Qualification (PPQ), ICH 3.2.S.2.6 batch comparability, and cGMP cleanroom operations (21 CFR Parts 210/211).",\n        "workflows": [\n            {"step": "1. Upstream Synthesis or Bioreactor Production", "plain": "Build the active ingredient in large chemical reactors or brew biologic proteins inside living cells.", "expert": "cGMP API synthesis or fed-batch/perfusion mammalian/microbial culture in single-use or stainless-steel bioreactors."},\n            {"step": "2. Downstream Purification & Isolation", "plain": "Filter and purify the active medicine until it meets pharmaceutical purity standards.", "expert": "Preparative chromatography skids, tangential flow filtration (TFF), viral inactivation/filtration, and crystallization."},\n            {"step": "3. Process Validation (PPQ) & cGMP Inspections", "plain": "Run consecutive full-scale batches to prove the factory produces consistent quality before regulators inspect the site.", "expert": "Stage 1–3 FDA Process Validation, Pre-Approval Inspections (PAI), and ongoing Continued Process Verification (CPV)."},\n        ],\n        "regulatory_anchors": [\n            {"label": "FDA Guidance: Process Validation — General Principles and Practices", "url": "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/process-validation-general-principles-and-practices"},\n            {"label": "FDA cGMP for Finished Pharmaceuticals (21 CFR Part 211)", "url": "https://www.ecfr.gov/current/title-21/chapter-I/subchapter-C/part-211"},\n        ],\n        "equipment_ids": ["eq-single-use-bioreactor", "eq-lyophilizer", "eq-sterile-fill-finish"],\n        "related_links": [\n            {"title": "Manufacturers, CDMOs & Site Audits", "href": "#/ref/vendors", "text": "Compare manufacturing sites by stage, modality, and FDA/EMA audit history."},\n            {"title": "How Medicines Are Made (By Modality)", "href": "#/explore/made", "text": "Compare chemical synthesis, fermentation, and recombinant cells."},\n        ],\n    },\n]\n\n\ndef _catalogue_modality_counts(data_dir: pathlib.Path) -> dict:\n    drugs_dir = data_dir / "drugs"\n    if not drugs_dir.is_dir():\n        return {}\n    counts = {}\n    for fp in drugs_dir.glob("*.json"):\n        d = json.loads(fp.read_text(encoding="utf-8"))\n        t = d.get("type") or "Unknown"\n        counts[t] = counts.get(t, 0) + 1\n    return counts\n\n\ndef build_departments(data_dir: pathlib.Path) -> dict:\n    data_dir.mkdir(parents=True, exist_ok=True)\n    mod_counts = _catalogue_modality_counts(data_dir)\n    payload = {\n        "checked": CHECKED,\n        "department_count": len(DEPARTMENTS),\n        "route_count": len(ROUTES_OF_ADMINISTRATION),\n        "catalogue_modality_counts": mod_counts,\n        "departments": DEPARTMENTS,\n        "routes": ROUTES_OF_ADMINISTRATION,\n    }\n    out_path = data_dir / "departments.json"\n    out_path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\\n", encoding="utf-8")\n    return {\n        "written": str(out_path),\n        "departments": len(DEPARTMENTS),\n        "routes": len(ROUTES_OF_ADMINISTRATION),\n        "catalogue_types_counted": len(mod_counts),\n    }\n\n\nif __name__ == "__main__":\n    if len(sys.argv) < 2:\n        sys.exit("Usage: python3 pipeline/build_departments.py <site/data>")\n    print(json.dumps(build_departments(pathlib.Path(sys.argv[1])), indent=2))\n'
DEPARTMENTS_JS = '// Pharmaceutical Encyclopedia: Departments & Routes of Administration (v6.0b)\n// Supports both Explore (#/explore/how-drugs-are-built, #/explore/departments/<id>)\n// and Reference (#/ref/departments, #/ref/departments/<id>, #/ref/routes).\nimport { html } from "./ui.js";\nimport * as data from "./data.js";\nimport { page } from "./layout.js";\n\nconst EXP_HOME = ["Home", "#/explore"];\nconst REF_HOME = ["Overview", "#/ref"];\n\nexport const departmentsData = () => data.getJSON("data/departments.json");\n\nfunction sourceLinks(sources = [], checked) {\n  if (!sources.length) return "";\n  return html`<p class="muted small">Sources: ${sources.map((s, i) =>\n    html`${i ? " · " : ""}<a href="${s.url}" target="_blank" rel="noopener">${s.label}</a>`)}${checked ? ` (checked ${checked})` : ""}.</p>`;\n}\n\nexport async function departmentsExplorePage(deptId = null) {\n  const doc = await departmentsData();\n  if (!deptId) {\n    const cards = doc.departments.map((d) => html`\n      <section class="x-panel">\n        <h2>${d.icon} <a href="#/explore/departments/${d.id}">${d.name}</a></h2>\n        <p class="who">${d.stage_range}</p>\n        <p>${d.plain_summary}</p>\n        <p><a href="#/explore/departments/${d.id}">Explore this department →</a></p>\n      </section>`);\n    return {\n      html: page({\n        trail: [EXP_HOME, ["How drugs are built"]],\n        title: "Inside a Pharmaceutical Company",\n        lede: "How a molecule travels from an early lab idea to a safe, tested medicine on a pharmacy shelf—department by department.",\n        body: html`${cards}`,\n        more: [{ title: "Technical Reference View", text: "CQAs, ICH guidelines, and routes of administration.", href: "#/ref/departments" }],\n      }),\n    };\n  }\n\n  const dept = doc.departments.find((d) => d.id === deptId);\n  if (!dept) throw new Error(`Department not found: ${deptId}`);\n  const body = html`\n    <section class="x-panel"><h2>What this team does</h2><p>${dept.plain_summary}</p></section>\n    <section class="x-panel"><h2>Step by step</h2>\n      <ul class="plain">${dept.workflows.map((w) => html`<li><b>${w.step}:</b> ${w.plain}</li>`)}</ul>\n      ${sourceLinks(dept.regulatory_anchors, doc.checked)}\n    </section>\n    ${dept.id === "formulation" ? html`<section class="x-panel"><h2>How medicines enter the body</h2>\n      <ul class="plain">${doc.routes.map((r) => html`<li><b>${r.name}:</b> ${r.plain_summary}</li>`)}</ul></section>` : ""}`;\n  return {\n    html: page({\n      level: "deep",\n      trail: [EXP_HOME, ["How drugs are built", "#/explore/how-drugs-are-built"], [dept.name]],\n      kicker: dept.stage_range,\n      title: `${dept.icon} ${dept.name}`,\n      body,\n      more: [{ title: "Technical Reference View", text: "CQAs, ICH standards, and equipment specs.", href: `#/ref/departments/${dept.id}` }],\n    }),\n  };\n}\n\nexport async function departmentsRefPage(deptId = null) {\n  const doc = await departmentsData();\n  if (!deptId) {\n    const rows = doc.departments.map((d) => html`<tr>\n      <td><a href="#/ref/departments/${d.id}"><b>${d.icon} ${d.name}</b></a></td>\n      <td>${d.stage_range}</td>\n      <td>${d.workflows.length} core workflows</td>\n      <td>${d.equipment_ids.length} linked hardware classes</td>\n    </tr>`);\n    const body = html`\n      <div class="tbl-wrap" tabindex="0" role="region" aria-label="Pharmaceutical departments">\n        <table class="tbl"><thead><tr><th>Department</th><th>Lifecycle Stage</th><th>Workflows</th><th>Equipment</th></tr></thead>\n        <tbody>${rows}</tbody></table>\n      </div>\n      <p><a class="btn" href="#/ref/routes">Explore Routes of Administration</a> <a class="btn" href="#/ref/equipment">Equipment Market &amp; Specs</a></p>\n      <p class="muted small">Updated ${doc.checked}. Connects regulatory filings to R&amp;D, CMC formulation, analytical QC, and commercial manufacturing.</p>`;\n    return {\n      html: page({\n        trail: [REF_HOME, ["Departments"]],\n        title: "Pharmaceutical Encyclopedia — Departments",\n        lede: "End-to-end CMC, analytical, discovery, and manufacturing workflows linked to ICH/FDA guidance and hardware specifications.",\n        body,\n      }),\n    };\n  }\n\n  const dept = doc.departments.find((d) => d.id === deptId);\n  if (!dept) throw new Error(`Department not found: ${deptId}`);\n  const body = html`\n    <p>${dept.technical_summary}</p>\n    <h2>Core Technical Workflows</h2>\n    <div class="tbl-wrap" tabindex="0" role="region" aria-label="Department workflows">\n      <table class="tbl"><thead><tr><th>Stage / Workflow</th><th>Technical Scope &amp; Standards</th></tr></thead>\n      <tbody>${dept.workflows.map((w) => html`<tr><th scope="row">${w.step}</th><td>${w.expert}</td></tr>`)}</tbody></table>\n    </div>\n    <h2>Linked Equipment Categories</h2>\n    <p>${dept.equipment_ids.map((eid, i) => html`${i ? " · " : ""}<a href="#/ref/equipment?dept=${dept.id}#${eid}">${eid}</a>`)}</p>\n    ${sourceLinks(dept.regulatory_anchors, doc.checked)}`;\n\n  return {\n    html: page({\n      trail: [REF_HOME, ["Departments", "#/ref/departments"], [dept.name]],\n      kicker: dept.stage_range,\n      title: `${dept.icon} ${dept.name}`,\n      body,\n      more: dept.related_links || [],\n    }),\n  };\n}\n\nexport async function routesRefPage() {\n  const doc = await departmentsData();\n  const body = html`\n    <div class="tbl-wrap" tabindex="0" role="region" aria-label="Routes of administration">\n      <table class="tbl"><thead><tr><th>Route / Delivery System</th><th>Formulation Rationale</th><th>Critical Quality Attributes (CQAs)</th><th>Catalogue</th></tr></thead>\n      <tbody>${doc.routes.map((r) => html`<tr>\n        <th scope="row">${r.name}</th>\n        <td>${r.technical_rationale}</td>\n        <td><ul class="plain">${r.cqas.map((c) => html`<li>${c}</li>`)}</ul></td>\n        <td><a href="${r.catalogue_filter}">Browse medicines →</a></td>\n      </tr>`)}</tbody></table>\n    </div>\n    <p class="muted small">Updated ${doc.checked}. Every route links to FDA/ICH quality guidance and the corresponding hardware in <a href="#/ref/equipment">Equipment Market</a>.</p>`;\n  return {\n    html: page({\n      trail: [REF_HOME, ["Departments", "#/ref/departments"], ["Routes of Administration"]],\n      title: "Formulation & Routes of Administration",\n      lede: "How dosage forms and delivery systems are engineered to match each molecule\'s stability, bioavailability, and clinical use.",\n      body,\n      more: [\n        { title: "Formulation Development Department", text: "Preformulation, scale-up, and container-closure integrity.", href: "#/ref/departments/formulation" },\n        { title: "Analytical Development & QC", text: "Dissolution, HPLC/UPLC, stability, and impurity profiling.", href: "#/ref/departments/analytical" },\n      ],\n    }),\n  };\n}\n'


def apply_patch(root: pathlib.Path) -> dict:
    pipe_dir = root / "pipeline"
    js_dir = root / "site" / "js"
    pipe_dir.mkdir(parents=True, exist_ok=True)
    js_dir.mkdir(parents=True, exist_ok=True)
    (pipe_dir / "build_departments.py").write_text(BUILD_DEPARTMENTS_PY, encoding="utf-8")
    (js_dir / "departments.js").write_text(DEPARTMENTS_JS, encoding="utf-8")
    return {
        "pipeline_written": "pipeline/build_departments.py",
        "ui_written": "site/js/departments.js",
        "routes_ready": [
            "#/explore/how-drugs-are-built",
            "#/explore/departments/<id>",
            "#/ref/departments",
            "#/ref/departments/<id>",
            "#/ref/routes",
        ],
    }


def selftest() -> None:
    with tempfile.TemporaryDirectory() as td:
        root = pathlib.Path(td)
        data_dir = root / "site" / "data"
        (data_dir / "drugs").mkdir(parents=True)
        (data_dir / "drugs" / "aspirin.json").write_text(json.dumps({"id": "aspirin", "type": "Small molecule"}), encoding="utf-8")

        apply_patch(root)
        out = subprocess.run(
            [sys.executable, str(root / "pipeline" / "build_departments.py"), str(data_dir)],
            capture_output=True, text=True, check=True,
        )
        res = json.loads(out.stdout)
        assert res["departments"] == 4 and res["routes"] == 5 and res["catalogue_types_counted"] == 1, res

        doc = json.loads((data_dir / "departments.json").read_text(encoding="utf-8"))
        for d in doc["departments"]:
            assert d["id"] and d["plain_summary"] and d["technical_summary"] and d["workflows"]
            assert d["regulatory_anchors"] and all(a["url"].startswith("https://") for a in d["regulatory_anchors"])
        for r in doc["routes"]:
            assert r["id"] and r["cqas"] and r["equipment_ids"]
            assert r["sources"] and all(s["url"].startswith("https://") for s in r["sources"])

        js_txt = (root / "site" / "js" / "departments.js").read_text(encoding="utf-8")
        assert "export async function departmentsExplorePage" in js_txt
        assert "export async function departmentsRefPage" in js_txt
        assert "export async function routesRefPage" in js_txt
        print("V60B_PHARMA_ENCYCLOPEDIA_SELFTEST_PASSED", json.dumps(res, indent=2))


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="Apply Pill by Pill v6.0b Pharma Encyclopedia Departments patch.")
    ap.add_argument("--apply", type=pathlib.Path, help="Path to unpacked source directory")
    ap.add_argument("--selftest", action="store_true", help="Run built-in verification tests")
    args = ap.parse_args(argv)
    if args.selftest:
        selftest()
        return 0
    if args.apply:
        print(json.dumps(apply_patch(args.apply), indent=2))
        return 0
    ap.error("Provide --apply <dir> or --selftest")
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
